class TestHelperFunctions:
    """Test the helper functions used by the stemmer."""
    
    def test_contains_vowel(self):
        """Test contains_vowel function."""
        assert contains_vowel("sky") is True      # y after consonant
        assert contains_vowel("by") is True       # y after consonant
        assert contains_vowel("fly") is True      # y after consonant
        assert contains_vowel("play") is True     # has 'a' and y
        assert contains_vowel("myth") is True     # y after consonant
        assert contains_vowel("rhythm") is True   # y after consonant
        assert contains_vowel("psst") is False    # no vowels
        assert contains_vowel("crypt") is True    # y after consonant
        assert contains_vowel("tsktsk") is False  # no vowels
    
    def test_m_value(self):
        """Test m_value calculation."""
        # Words with m=0
        assert m_value("sky") == 0       # C V
        assert m_value("by") == 0        # C V
        assert m_value("tree") == 0      # C C V V
        assert m_value("f") == 0         # C
        
        # Words with m=1
        assert m_value("play") == 1      # C C V C
        assert m_value("yes") == 1       # C V C
        assert m_value("happy") == 1     # C V C C V
        assert m_value("agr") == 1       # V C C
        assert m_value("trouble") == 1   # C V C V

        # Words with m=2
        assert m_value("syzygy") == 2    # C V C V C V
        
        # Words with m=3
        assert m_value("beautiful") == 3 # C V C V C V C
        
        # Edge cases
        assert m_value("") == 0
        assert m_value("a") == 0
        assert m_value("ab") == 1        # V C 
    
    def test_star_o(self):
        """Test star_o function."""
        # Words ending in CVC where last C is not W, X, Y
        assert star_o("hop") is True     # h-o-p (C-V-C, p not w/x/y)
        assert star_o("wil") is True     # w-i-l (C-V-C, l not w/x/y)
        assert star_o("vet") is True     # v-e-t (C-V-C, t not w/x/y)
        
        # Words ending in CVC where last C is W, X, or Y
        assert star_o("low") is False    # l-o-w (w is invalid)
        assert star_o("tax") is False    # t-a-x (x is invalid)
        assert star_o("say") is False    # s-a-y (y is invalid)
        
        # Words not ending in CVC
        assert star_o("hoping") is False # too long
        assert star_o("at") is False     # too short
        assert star_o("") is False       # empty
        assert star_o("ab") is False     # too short


class TestStep1a:
    """Test Step 1a: Plurals and past participles."""
    
    def test_sses_to_ss(self):
        """SSES -> SS."""
        assert step_1a("caresses") == "caress"
        assert step_1a("presses") == "press"
        assert step_1a("misses") == "miss"
    
    def test_ies_to_i(self):
        """IES -> I."""
        assert step_1a("ponies") == "poni"
        assert step_1a("ties") == "ti"
        assert step_1a("cries") == "cri"
        assert step_1a("flies") == "fli"
    
    def test_ss_unchanged(self):
        """SS -> SS (no change)."""
        assert step_1a("press") == "press"
        assert step_1a("class") == "class"
    
    def test_s_removal(self):
        """S -> (nothing)."""
        assert step_1a("cats") == "cat"
        assert step_1a("dogs") == "dog"
        assert step_1a("cars") == "car"
    
    def test_no_change(self):
        """Words that shouldn't change."""
        assert step_1a("cat") == "cat"
        assert step_1a("dog") == "dog"
        assert step_1a("car") == "car"


class TestStep1b:
    """Test Step 1b: Past participles and progressive forms."""
    
    def test_eed_to_ee(self):
        """(m>0) EED -> EE."""
        assert step_1b("agreed") == "agree"
        
        assert step_1b("bled") == "bled"      # no "eed"
    
    def test_ed_removal(self):
        """(*v*) ED ->."""
        assert step_1b("plastered") == "plaster"
        assert step_1b("motored") == "motor"
        assert step_1b("bled") == "bled"      # no vowel, so no change
        assert step_1b("feed") == "feed"      # common suffix -eed first, condition doesnt match so return original
    
    def test_ing_removal(self):
        """(*v*) ING ->."""
        assert step_1b("motoring") == "motor"
        assert step_1b("running") == "run"    # extra_step handles double consonant
        assert step_1b("sing") == "sing"      # no vowel, so no change
    
    def test_extra_step_at(self):
        """AT -> ATE in extra_step."""
        assert step_1b("conflated") == "conflate"
    
    def test_extra_step_bl(self):
        """BL -> BLE in extra_step."""
        assert step_1b("troubled") == "trouble"
    
    def test_extra_step_iz(self):
        """IZ -> IZE in extra_step."""
        assert step_1b("sized") == "size"
    
    def test_extra_step_double_cons(self):
        """Double consonant removal in extra_step."""
        assert step_1b("hopped") == "hop"
        assert step_1b("tanned") == "tan"
        assert step_1b("falling") == "fall"    # 'll' stays because l is special
        assert step_1b("hissing") == "hiss"    # 'ss' stays because s is special


class TestStep1c:
    """Test Step 1c: Y -> I."""
    
    def test_y_to_i(self):
        """(*v*) Y -> I."""
        assert step_1c("happy") == "happi"
        assert step_1c("sky") == "sky"        # no vowel before y? Actually "sky" has vowel y after consonant
        # Wait, "sky" has y after consonant, so it should change?
        # Let me check: "sky" → s(c) k(c) y(v) → contains_vowel("sk") is False
        # So no change
        assert step_1c("fly") == "fly"        # no vowel before y
        assert step_1c("by") == "by"          # no vowel before y
        assert step_1c("cry") == "cry"        # no vowel before y
        assert step_1c("deny") == "deni"      # "den" has vowel 'e'


