class TestStep5:
    """Test Steps 5a and 5b: Tidying up."""
    
    def test_step5a_m_gt_1(self):
        """(m>1) E ->."""
        assert step_5a("probate") == "probat"
        assert step_5a("rate") == "rate"  # m=1, not *o, so no change
        assert step_5a("cease") == "ceas" # m=1, not *o? Actually "cea" has m=1, not *o → remove e
    
    def test_step5a_m_eq_1_not_star_o(self):
        """(m=1 and not *o) E ->."""
        assert step_5a("cease") == "ceas"
        # "cease" → stem "cea" → m=1, not *o → remove e
    
    def test_step5a_no_change(self):
        """Words that shouldn't change."""
        assert step_5a("rate") == "rate"   # m=1 and *o? "rat" = CVC, last char t not w/x/y → *o is True
        # Actually "rate" → stem "rat" → m=1, *o=True → don't remove e
    
    def test_step5b_double_consonant(self):
        """(m > 1 and *d and *L) -> single letter."""
        assert step_5b("controll") == "control"
        assert step_5b("roll") == "roll"   # m=1, so no change
        assert step_5b("stroll") == "stroll" # m=1? Actually "stroll" has m=1? No, "stroll" = s-t-r-o-l-l → C-C-C-V-C-C → m=1
        # So no change


class TestFullStemmer:
    """Test the complete Porter Stemmer with real words."""
    
    def test_common_words(self):
        """Test common English words."""
        test_cases = [
            ("running", "run"),
            ("ran", "ran"),
            ("runs", "run"),
            ("cats", "cat"),
            ("caresses", "caress"),
            ("ponies", "poni"),
            ("trouble", "troubl"),
            ("troubled", "troubl"),
            ("troubling", "troubl"),
            ("agreed", "agre"),
            ("agreement", "agreement"),
            ("happiness", "happi"),
            ("beautiful", "beauti"),
            ("effective", "effect"),
            ("national", "nation"),  # Wait, this should be "nation" not "nat"
            # Let me verify: "national" → "nation" 
        ]
        
        for word, expected in test_cases:
            result = porter_transform(word)
            assert result == expected, f"'{word}' → '{result}' (expected '{expected}')"
    
    def test_stem_tokens(self):
        """Test stemming a list of tokens."""
        tokens = ["running", "ran", "runs", "runner"]
        result = stem_tokens(tokens)
        
        # All should stem to "run"
        expected = ["run", "ran", "run", "runner"]
        assert sorted(result[0]) == sorted(expected)
    
    def test_stem_tokens_with_duplicates(self):
        """Test that duplicates are removed."""
        tokens = ["cat", "cat", "cats", "cat"]
        result = stem_tokens(tokens)
        expected = ["cat"]
        assert sorted(result[1]) == sorted(expected)


